<?php

namespace App\Http\Requests;

use App\Enums\Commune;
use Illuminate\Contracts\Validation\ValidationRule;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * Studio data shared by the create and edit forms. The slug and the
 * enrollment token are generated by the model; the rules arrive in phase 2.
 */
class StudioRequest extends FormRequest
{
    /**
     * Get the validation rules that apply to the request.
     *
     * @return array<string, ValidationRule|array<mixed>|string>
     */
    public function rules(): array
    {
        return [
            'name' => ['required', 'string', 'max:100', 'regex:/[\pL\pN]/u'],
            'commune' => ['required', Rule::enum(Commune::class)],
        ];
    }

    /**
     * The validated studio name, without surrounding spaces.
     */
    public function studioName(): string
    {
        return $this->string('name')->trim()->value();
    }

    /**
     * The validated commune.
     */
    public function commune(): Commune
    {
        return Commune::from($this->string('commune')->value());
    }

    /**
     * Get the custom messages for validator errors.
     *
     * @return array<string, string>
     */
    public function messages(): array
    {
        return [
            'name.regex' => __('The name must include letters or numbers.'),
        ];
    }
}
